1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	// --- Quotes ------------------------------------------------------------------
52	
53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	// Charged on every quote, unconditionally — it is the cost of assessing the
65	// items, not a penalty for being a new customer. Named "first insurance" in
66	// some of the domain material, which misleads: it does not depend on customer
67	// history or on the quote's position in the scenario.
68	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
69	
70	const WHOLE_PERCENT = 100;
71	
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / WHOLE_PERCENT;
74	
75	// The tables keyed by item type cover exactly the types the MHPCO insures.
76	// Anything else is not a mispriced item, it is not an item at all, so a lookup
77	// miss is an error rather than a zero. `priceName` names the price the table
78	// holds, so the rejection can say which one the item had none of.
79	const lookUpByItemType = (
80	  table: Record<string, number>,
81	  item: Item,
82	  priceName: string,
83	): number => {
84	  const value = table[item.type];
85	
86	  if (value === undefined) {
87	    throw new Error(`unknown item type "${item.type}": no ${priceName}`);
88	  }
89	
90	  return value;
91	};
92	
93	const itemBasePremium = (item: Item): number =>
94	  lookUpByItemType(BASE_PREMIUM_BY_TYPE, item, "base premium");
95	
96	const BLOCK_SIZE = 3;
97	
98	const BLOCK_PREMIUM = 60;
99	
100	const sumOf = (amounts: number[]): number =>
101	  amounts.reduce((sum, amount) => sum + amount, 0);
102	
103	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
104	
105	const sumOfItemBasePremiums = (items: Item[]): number =>
106	  sumOf(items.map(itemBasePremium));
107	
108	// Grouping by type is the one piece of knowledge shared by the two places that
109	// care about how many of a kind there are: premiums price alike items together,
110	// and a claim compares damaged counts against insured counts. Both take their
111	// key from a type field, so `typeOf` says which field on the element that is.
112	const groupByType = <T>(
113	  elements: T[],
114	  typeOf: (element: T) => string,
115	): Map<string, T[]> => {
116	  const groups = new Map<string, T[]>();
117	
118	  for (const element of elements) {
119	    const type = typeOf(element);
120	    groups.set(type, [...(groups.get(type) ?? []), element]);
121	  }
122	
123	  return groups;
124	};
125	
126	const itemType = (item: Item): string => item.type;
127	
128	// Items of the same type are "alike" and are priced together, so the policy
129	// base premium is computed group by group rather than item by item.
130	const alikeGroups = (items: Item[]): Item[][] => [
131	  ...groupByType(items, itemType).values(),
132	];
133	
134	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
135	  formsABlock(alikeItems)
136	    ? BLOCK_PREMIUM
137	    : sumOfItemBasePremiums(alikeItems);
138	
139	const policyBasePremium = (items: Item[]): number =>
140	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
141	
142	const roundPremiumInMHPCOsFavor = (amount: number): number =>
143	  Math.ceil(amount);
144	
145	// The inputs a single quote is computed from: `items` drives the base premium
146	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
147	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
148	// general — a claim step is not a contract and must not trigger the follow-up
149	// discount.
150	type QuoteRequest = {
151	  customer: Customer;
152	  items: Item[];
153	  precedingQuoteCount: number;
154	};
155	
156	const LOYALTY_YEARS = 2;
157	
158	const LOYALTY_DISCOUNT_PERCENT = 20;
159	
160	// Modifier percents are signed so surcharges and discounts can be summed
161	// uniformly; a discount enters the sum as its negation.
162	const asDiscount = (percent: number): number => -percent;
163	
164	const isLoyal = (customer: Customer): boolean =>
165	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
166	
167	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
168	
169	const isFollowUpContract = (request: QuoteRequest): boolean =>
170	  request.precedingQuoteCount > 0;
171	
172	const policyModifierPercents = (request: QuoteRequest): number[] => [
173	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
174	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
175	  ...(isFollowUpContract(request)
176	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
177	    : []),
178	];
179	
180	// Policy-wide modifiers do NOT compound: each is an independent percentage of
181	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
182	// would give a different, wrong answer.
183	const applyPolicyModifiers = (
184	  basePremium: number,
185	  request: QuoteRequest,
186	): number =>
187	  basePremium +
188	  sumOf(
189	    policyModifierPercents(request).map((percent) =>
190	      percentOf(basePremium, percent),
191	    ),
192	  );
193	
194	const CURSE_SURCHARGE_PERCENT = 50;
195	
196	const HIGH_ENCHANTMENT_LEVEL = 5;
197	
198	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
199	
200	const isHighlyEnchanted = (item: Item): boolean =>
201	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
202	
203	const isCursed = (item: Item): boolean => item.cursed === true;
204	
205	type ItemSurchargeRule = {
206	  applies: (item: Item) => boolean;
207	  percent: number;
208	};
209	
210	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
211	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
212	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
213	];
214	
215	// Item-scoped surcharges are charged on the item's own base premium, so they
216	// must NOT go through applyPolicyModifiers.
217	const itemSurcharges = (item: Item): number =>
218	  sumOf(
219	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
220	      percentOf(itemBasePremium(item), rule.percent),
221	    ),
222	  );
223	
224	const policyItemSurcharges = (items: Item[]): number =>
225	  sumOf(items.map(itemSurcharges));
226	
227	const quotePremium = (request: QuoteRequest): number =>
228	  roundPremiumInMHPCOsFavor(
229	    applyPolicyModifiers(policyBasePremium(request.items), request) +
230	      policyItemSurcharges(request.items) +
231	      PROCESSING_FEE,
232	  );
233	
234	// --- Claims -----------------------------------------------------------------
235	// An item's insurance value is what it is worth if destroyed, and is unrelated
236	// to its premium: the premium is what the customer pays to be covered. The two
237	// tables below happen to agree on a 10x ratio today, but that is a property of
238	// the current price list and not a rule of the domain — repricing premiums must
239	// not silently revalue payouts, so they stay separate.
240	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
241	  sword: 1000,
242	  amulet: 600,
243	  staff: 800,
244	  potion: 400,
245	  rune: 250,
246	  moonstone: 250,
247	};
248	
249	const itemInsuranceValue = (item: Item): number =>
250	  lookUpByItemType(INSURANCE_VALUE_BY_TYPE, item, "insurance value");
251	
252	const insuranceSum = (items: Item[]): number =>
253	  sumOf(items.map(itemInsuranceValue));
254	
255	// A policy pays out at most twice what it insures.
256	const CAP_MULTIPLIER = 2;
257	
258	const policyCap = (items: Item[]): number =>
259	  CAP_MULTIPLIER * insuranceSum(items);
260	
261	// The MHPCO's favour cuts the other way for money it pays out than for money
262	// it collects: premiums round up, payouts round down.
263	const roundPayoutInMHPCOsFavor = (amount: number): number => Math.floor(amount);
264	
265	const DEDUCTIBLE = 100;
266	
267	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
268	
269	const HALF_REIMBURSEMENT_PERCENT = 50;
270	
271	const isHalfReimbursed = (item: Item): boolean =>
272	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
273	
274	const DRAGON_MATERIAL = "dragon";
275	
276	const isDragonMaterial = (item: Item): boolean =>
277	  item.material === DRAGON_MATERIAL;
278	
279	// A damage entry names the item it damaged by type. The MHPCO only reimburses
280	// what it insured, so a type the policy does not cover is a rejection rather
281	// than an uncovered-but-tolerated entry.
282	const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
283	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
284	
285	  if (item === undefined) {
286	    throw new Error(
287	      `damaged item "${damage.itemType}" is not covered by this policy`,
288	    );
289	  }
290	
291	  return item;
292	};
293	
294	const FULL_REIMBURSEMENT_PERCENT = 100;
295	
296	// A reimbursement clause pays a stated percentage of the damage. Clauses are
297	// listed in precedence order and the first applicable one wins.
298	type ReimbursementClause = {
299	  applies: (item: Item) => boolean;
300	  percent: number;
301	};
302	
303	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
304	  // Half reimbursement outranks the dragon clause: the spec's "50 % rule wins"
305	  // example is a dragon-material item enchanted to 8, and it pays out half.
306	  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
307	  // "Damage to items made of dragon material is fully reimbursed." This clause
308	  // is currently indistinguishable from the fallback below — every example it
309	  // matches would reimburse in full anyway, so removing it would not change a
310	  // single result, and no test can tell it is here. It is stated regardless
311	  // because it is a rule the domain asserts about dragon material, not an
312	  // accident of what the other rules happen to leave over. Should a future rule
313	  // ever reduce reimbursement below 100 % for some other reason, dragon items
314	  // must keep their full payout, and this line is what will say so.
315	  { applies: isDragonMaterial, percent: FULL_REIMBURSEMENT_PERCENT },
316	];
317	
318	// An item no clause matches is reimbursed in full: that is the domain's
319	// default, not a fallback for a missing item. `damagedItem` now rejects a
320	// damage naming a type the policy does not cover, so there is no such thing
321	// here as an item that isn't there.
322	const reimbursementPercent = (item: Item): number =>
323	  REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.percent ??
324	  FULL_REIMBURSEMENT_PERCENT;
325	
326	// A damage is something that happened to an item; a negative one is not a
327	// smaller damage but a nonsensical report, so it is rejected rather than
328	// netted off against the rest of the claim.
329	const damageAmount = (damage: Damage): number => {
330	  if (damage.amount < 0) {
331	    throw new Error(
332	      `damage amount ${damage.amount} for "${damage.itemType}" is negative`,
333	    );
334	  }
335	
336	  return damage.amount;
337	};
338	
339	// What a damage entry reimburses before the deductible: a percentage of the
340	// damage amount, decided by the clauses covering the damaged item.
341	const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
342	  percentOf(
343	    damageAmount(damage),
344	    reimbursementPercent(damagedItem(insuredItems, damage)),
345	  );
346	
347	// The deductible applies once per damage event, i.e. per entry in `damages`,
348	// and always last — after the clause has decided the reimbursable amount.
349	const damagePayout = (insuredItems: Item[], damage: Damage): number =>
350	  reimbursableAmount(insuredItems, damage) - DEDUCTIBLE;
351	
352	// --- Running a scenario ------------------------------------------------------
353	
354	const isQuote = (step: Step): boolean => step.op === "quote";
355	
356	// What the scenario has accumulated so far. Steps are folded rather than mapped
357	// because a step's result depends on the steps before it: `precedingQuoteCount`
358	// drives the follow-up discount today, and claim steps will thread a remaining
359	// cap through the same carry.
360	// A policy as it stands at some point in the scenario: what it insures, and how
361	// much of its cap is left. The remaining cap belongs to the policy rather than
362	// to a side table because successive claims spend it down — it is the one part
363	// of a policy that changes over the scenario's lifetime.
364	type Policy = {
365	  insuredItems: Item[];
366	  remainingCap: number;
367	};
368	
369	const issuePolicy = (insuredItems: Item[]): Policy => ({
370	  insuredItems,
371	  remainingCap: policyCap(insuredItems),
372	});
373	
374	type ScenarioState = {
375	  results: StepResult[];
376	  precedingQuoteCount: number;
377	  // Policies issued by earlier quote steps, keyed by that step's index — a
378	  // claim names its policy that way (`step.policy`).
379	  policiesByStep: Map<number, Policy>;
380	};
381	
382	const INITIAL_STATE: ScenarioState = {
383	  results: [],
384	  precedingQuoteCount: 0,
385	  policiesByStep: new Map(),
386	};
387	
388	const withPolicy = (
389	  state: ScenarioState,
390	  stepIndex: number,
391	  policy: Policy,
392	): ScenarioState => ({
393	  ...state,
394	  policiesByStep: new Map(state.policiesByStep).set(stepIndex, policy),
395	});
396	
397	// Running a step is a state transition: it reads the carry accumulated by the
398	// preceding steps and returns the next carry. Every step kind gets its own
399	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
400	// will be added without touching the quote path.
401	type StepRunner = (
402	  customer: Customer,
403	  state: ScenarioState,
404	  step: Step,
405	  stepIndex: number,
406	) => ScenarioState;
407	
408	const appendResult = (
409	  state: ScenarioState,
410	  result: StepResult,
411	): ScenarioState => ({ ...state, results: [...state.results, result] });
412	
413	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
414	  const items = step.items ?? [];
415	
416	  const premium = quotePremium({
417	    customer,
418	    items,
419	    precedingQuoteCount: state.precedingQuoteCount,
420	  });
421	
422	  return withPolicy(
423	    {
424	      ...appendResult(state, { premium }),
425	      precedingQuoteCount: state.precedingQuoteCount + 1,
426	    },
427	    stepIndex,
428	    issuePolicy(items),
429	  );
430	};
431	
432	// A claim names its policy by the index of the quote step that issued it. A
433	// claim that names no policy, or names one no quote step issued, is not a claim
434	// for 0 G — there is nothing to claim against, so it is rejected. Resolving
435	// yields the key as well as the policy, so that debiting the cap later needs no
436	// second, separately-justified lookup of `step.policy` — the key travelled with
437	// the thing it addresses.
438	type ClaimedPolicy = { key: number; policy: Policy };
439	
440	const claimedPolicy = (state: ScenarioState, step: Step): ClaimedPolicy => {
441	  const key = step.policy;
442	
443	  if (key === undefined) {
444	    throw new Error("claim names no policy");
445	  }
446	
447	  const policy = state.policiesByStep.get(key);
448	
449	  if (policy === undefined) {
450	    throw new Error(`claim against unknown policy ${key}`);
451	  }
452	
453	  return { key, policy };
454	};
455	
456	const countsByType = <T>(
457	  elements: T[],
458	  typeOf: (element: T) => string,
459	): Map<string, number> =>
460	  new Map(
461	    [...groupByType(elements, typeOf)].map(([type, group]) => [
462	      type,
463	      group.length,
464	    ]),
465	  );
466	
467	const damagedType = (damage: Damage): string => damage.itemType;
468	
469	// Each damage entry is a separate damaged item, so a policy insuring one sword
470	// cannot suffer two sword damages. Over-claiming rejects the whole claim rather
471	// than the offending entry — the MHPCO does not part-settle a suspect report.
472	const rejectOverClaiming = (insuredItems: Item[], damages: Damage[]): void => {
473	  const insuredCounts = countsByType(insuredItems, itemType);
474	
475	  for (const [type, claimed] of countsByType(damages, damagedType)) {
476	    const insured = insuredCounts.get(type) ?? 0;
477	
478	    if (claimed > insured) {
479	      throw new Error(
480	        `claim reports ${claimed} damaged "${type}" but the policy covers ${insured}`,
481	      );
482	    }
483	  }
484	};
485	
486	const runClaimStep: StepRunner = (_customer, state, step) => {
487	  const damages = step.incident?.damages ?? [];
488	  const { key, policy } = claimedPolicy(state, step);
489	  const { insuredItems, remainingCap } = policy;
490	
491	  rejectOverClaiming(insuredItems, damages);
492	
493	  // The clamp is outside the per-damage sum: the whole claim is limited by
494	  // what is left of the policy's cap, not each damage individually.
495	  // Per-damage amounts stay fractional; only the claim's total is rounded, and
496	  // it is rounded before the cap is spent down so the cap stays whole too.
497	  const desiredPayout = roundPayoutInMHPCOsFavor(
498	    sumOf(damages.map((damage) => damagePayout(insuredItems, damage))),
499	  );
500	  const payout = Math.min(desiredPayout, remainingCap);
501	  const capAfterClaim = remainingCap - payout;
502	
503	  return withPolicy(
504	    appendResult(state, { payout, remainingCap: capAfterClaim }),
505	    key,
506	    { ...policy, remainingCap: capAfterClaim },
507	  );
508	};
509	
510	const runStep: StepRunner = (customer, state, step, stepIndex) =>
511	  isQuote(step)
512	    ? runQuoteStep(customer, state, step, stepIndex)
513	    : runClaimStep(customer, state, step, stepIndex);
514	
515	// The customer is scenario-wide, so it is closed over rather than threaded
516	// through the fold alongside the per-step state.
517	const stepRunnerFor =
518	  (customer: Customer) =>
519	  (state: ScenarioState, step: Step, stepIndex: number) =>
520	    runStep(customer, state, step, stepIndex);
521	
522	export const runScenario = (scenario: Scenario): ScenarioResults => ({
523	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
524	    .results,
525	});
